'use strict';
const game=BUKGames.find(g=>g.id===new URLSearchParams(location.search).get('game'));
const target=document.getElementById('game-detail');
if(!game){target.innerHTML='<div class="empty-state"><h1>No encontramos ese juego.</h1><a class="button lime" href="./#juegos">Volver al catálogo</a></div>';}else{
 document.title=`${game.name} · Cómo jugar · BUKLABS Play`;
 document.querySelector('meta[name="description"]').content=game.pitch;
 target.innerHTML=`<a class="back-link" href="./#juegos">← Volver a los juegos</a><section class="detail-hero"><img class="detail-art" src="${game.image}" alt="Portada de ${game.name}" width="1536" height="1024"><div class="detail-copy"><img class="detail-logo" src="${game.logo}" alt="${game.name}" width="2048" height="682"><div class="eyebrow">CREADO POR BUKLABS · ${game.tag}</div><h1>${game.hook}</h1><p>${game.pitch}</p><div class="detail-meta"><span>${game.players}</span><span>${game.time} aprox.</span><span>${game.content}</span></div><div class="detail-actions"><a class="button lime" href="games/${game.id}/">Jugar ahora ↗</a><a class="button outline" href="#como-jugar">Cómo jugar ↓</a></div><p class="detail-note">Un dispositivo compartido · Juega desde el navegador<br>La duración depende de la cantidad de participantes y rondas.</p></div></section><div class="detail-body"><section class="detail-panel" id="como-jugar"><span class="eyebrow">SE APRENDE EN UNA RONDA</span><h2>Cómo se juega</h2><ol class="rules-list">${game.rules.map(rule=>`<li>${rule}</li>`).join('')}</ol><p class="tip">${game.tip}</p></section><section class="detail-panel"><span class="eyebrow">PRUÉBALO AQUÍ</span><h2>Así se siente jugar</h2><div id="demo" class="demo"></div><p class="detail-note">Ejemplo de las reglas. Esta demostración no suma puntos a tus partidas.</p></section><section class="detail-panel"><span class="eyebrow">QUE NO HAYA DISCUSIÓN</span><h2>Los puntos, claros</h2><table class="score-table" aria-label="Puntuación de ${game.name}"><tbody>${game.scoring.map(([action,points])=>`<tr><td>${action}</td><td>${points}</td></tr>`).join('')}</tbody></table></section><section class="detail-panel"><span class="eyebrow">A TU RITMO</span><h2>Qué incluye</h2><ul class="detail-options">${game.options.map(option=>`<li>${option}</li>`).join('')}</ul><p><strong>Ideal:</strong> ${game.ideal}</p></section></div><section class="detail-bottom"><div><strong>Los tres juegos en una sola app.</strong><p>También puedes jugar sin instalar. Para jugar offline, espera «Listo sin conexión».</p><p data-offline-state>Guardando juegos…</p></div><button class="button lime" data-buk="install">Instalar BUKLABS Play ↓</button></section>`;
 const demo=document.getElementById('demo');
 if(game.id==='blockbuster'){
  let revealed=1;const clues=['Un viaje de lujo termina en tragedia.','Dos jóvenes de mundos distintos se enamoran.','La historia transcurre en un gran transatlántico.','Un iceberg cambia el destino de todos.','Sus protagonistas se llaman Jack y Rose.'];
  function render(){demo.innerHTML=`<div class="demo-head"><span>¿Qué película es?</span><strong>${6-revealed} ${revealed===5?'punto':'puntos'}</strong></div>${clues.map((clue,i)=>`<div class="demo-clue"><span>0${i+1}</span>${i<revealed?clue:'Pista bloqueada'}</div>`).join('')}<button class="button lime" id="next-clue" ${revealed===5?'disabled':''}>${revealed===5?'Todas las pistas reveladas':'Otra pista · −1 punto'}</button> <button class="button outline" id="show-answer">Ver respuesta</button><p class="example-answer" id="answer" hidden>Titanic. Con ${revealed} ${revealed===1?'pista ganarías':'pistas ganarías'} ${6-revealed} ${revealed===5?'punto':'puntos'}.</p><button class="text-button" id="reset-demo">Reiniciar ejemplo ↻</button>`;document.getElementById('next-clue').onclick=()=>{if(revealed<5){revealed++;render();}};document.getElementById('show-answer').onclick=()=>{document.getElementById('answer').hidden=false;};document.getElementById('reset-demo').onclick=()=>{revealed=1;render();};}render();
 }else if(game.id==='ni-lo-digas'){
  demo.innerHTML='<div class="eyebrow">LA PALABRA ES</div><p class="sample-word">PALTA</p><p>Describe sin decir:</p><div class="forbidden"><span>Verde</span><span>Carozo</span><span>Guacamole</span><span>Untar</span><span>Fruta</span></div><button class="button lime" id="sample">Ver una descripción válida</button><p class="example-answer" id="answer" hidden>«En Chile se la ponemos al completo y también al pan del desayuno». Si tu equipo dice «palta», suma 1 punto.</p>';
  document.getElementById('sample').onclick=()=>{document.getElementById('answer').hidden=false;};
 }else{
  let index=0;const examples=[['¿Cuánto es 5 + 5?','Dos.'],['¿Qué animal hace miau?','Un elefante.'],['¿De qué color es el cielo despejado?','Fucsia.']];
  function render(){demo.innerHTML=`<div class="eyebrow">RESPONDE EN 3 SEGUNDOS</div><p class="sample-word">${examples[index][0]}</p><button class="button lime" id="sample">Ver una respuesta incorrecta</button><p class="example-answer" id="answer" hidden>«${examples[index][1]}» → +1 para quien responde. Es una de muchas respuestas posibles.</p><button class="text-button" id="another">Otro ejemplo →</button>`;document.getElementById('sample').onclick=()=>{document.getElementById('answer').hidden=false;};document.getElementById('another').onclick=()=>{index=(index+1)%examples.length;render();};}render();
 }
 if(window.BUK?.offlineReady)document.querySelectorAll('[data-offline-state]').forEach(el=>el.textContent='Listo sin conexión');
}
